public sealed interface Payment permits Pix, Card, BankSlip {}
public record Pix(String key) implements Payment {}
public record Card(String number, int installments) implements Payment {}
public record BankSlip(LocalDate dueDate) implements Payment {}

String describe(Payment p) {
    return switch (p) {                  // no default: the compiler knows all three
        case Pix pix -> "Pix " + pix.key();
        case Card c -> c.installments() + "x on card";
        case BankSlip b -> "Bank slip due " + b.dueDate();
    };
}

// WRONG: default hides new types
return switch (p) {
    case Pix pix -> "Pix";
    default -> "other";
};

// RIGHT: list every case; a new type makes this switch fail to compile until handled

if (obj instanceof String s && !s.isBlank()) {     // test + cast + variable
    System.out.println(s.toUpperCase());
}

record Point(int x, int y) {}

String format(Object value) {
    return switch (value) {
        case null -> "null";
        case Integer i when i > 1000 -> "big number " + i;
        case Integer i -> "number " + i;
        case String s -> "text " + s;
        case Point(int x, int y) -> "point " + x + "," + y;   // record pattern
        default -> value.toString();
    };
}

// WRONG: does not compile — "this case label is dominated by a preceding case label"
case Integer i -> "number " + i;
case Integer i when i > 1000 -> "big number " + i;

// RIGHT: specific first
case Integer i when i > 1000 -> "big number " + i;
case Integer i -> "number " + i;

