    @Override void setWidth(int w) { width = w; height = w; }
    @Override void setHeight(int h) { width = h; height = h; }
}

Rectangle r = new Square();
r.setWidth(5);
r.setHeight(4);
r.area();   // 16, but anyone using a Rectangle expects 20

