// Before: the class that does everything
class OrderService {
    void complete(Order o) {
        // calculates total, saves, generates PDF, sends email...
    }
}

// After: responsibilities separated and injected
class OrderService {
    private final OrderRepository repository;
    private final InvoiceGenerator invoices;
    private final List<Notifier> notifiers;      // OCP: add a channel = add a bean

    void complete(Order o) {
        repository.save(o);
        invoices.generate(o);
        notifiers.forEach(n -> n.orderCompleted(o));
    }
}

