interface DiscountPolicy {
    BigDecimal apply(BigDecimal amount);
}

@Component("BLACK_FRIDAY")
class BlackFridayDiscount implements DiscountPolicy {
    public BigDecimal apply(BigDecimal v) { return v.multiply(new BigDecimal("0.70")); }
}

@Component("NONE")
class NoDiscount implements DiscountPolicy {
    public BigDecimal apply(BigDecimal v) { return v; }
}

@Service
class PriceService {
    private final Map<String, DiscountPolicy> policies;   // all beans, keyed by name
    PriceService(Map<String, DiscountPolicy> policies) { this.policies = policies; }

    BigDecimal price(BigDecimal amount, String campaign) {
        DiscountPolicy policy = Optional.ofNullable(policies.get(campaign))
            .orElseThrow(() -> new IllegalArgumentException("Unknown campaign: " + campaign));
        return policy.apply(amount);
    }
}

// WRONG: a typo silently becomes "no discount"
policies.getOrDefault(campaign, policies.get("NONE")).apply(amount);

